        a, b, c = item[0], item[1], item[2]
        pattern = f"_{a}_{b}_{c}.txt"

        # 匹配成功则复制文件（包含 .txt 后面带后缀的情况）
        if pattern in file.name:
            print(f"复制文件: {file.name} -> {target_dir}/")
            shutil.copy(file, target_dir / file.name)
            break  # 避免同一个文件触发多次复制